mapper.select:
select w.code, w.title, w.status, w.priority, creator.real_name as creatorName, assignee.real_name as assigneeName, department.name as departmentName, w.create_time as createTime, w.update_time as updateTime, w.complete_time as completeTime from workorder w left join `user` creator on creator.id = w.creator_id left join `user` assignee on assignee.id = w.assignee_id left join department on department.id = w.department_id and department.is_del = 0 where w.is_del = 0
and w.creator_id = #{userId}
and w.assignee_id = #{userId}
and w.department_id = #{departmentId}
and w.title like concat('%', #{query.keyword}, '%')
and w.status in
#{status}
and w.priority in
#{priority}
and w.create_time >= #{query.startTime}
and w.create_time < #{query.endTimeExclusive}
order by w.update_time asc, w.create_time asc, w.code asc
order by w.update_time desc, w.create_time desc, w.code desc
order by w.create_time asc, w.code asc
order by w.create_time desc, w.code desc
